export enum MenuItemBehavior {
    Default = 0,
    HideForChildNavigation = 2,
    Hide = 4,
}
export interface MenuItem {
    /** Name to be displayed. */
    name: string;
    /** Url the menu item navigates to. */
    url: string;
    /** Child menu items used when there are multiple levels of navigation. */
    children: MenuItem[];

    /** When true, then menu item should be rendered */
    isAvailable?: boolean;
    /** Path to menu item used to build hierarchy */
    path: string;
    iconName?: string;
    cssClass?: string;
    isePiMenuItem?: boolean;
    behavior?: MenuItemBehavior;
    tooltip?: string;
    target?: string;
}

export interface Product {
    /** Name to be displayed. */
    name: string;
    /** Url the product navigates to. */
    url: string;
}

export interface CmsProduct extends Product {
    id: string;
    tooltip?: string;
    children?: MenuItem[];
}
