import { Context } from "@segment/analytics-next";

export type TelemetryPayload = Record<string, string | number | boolean | undefined | null>;
export interface ITelemetry {
    track(origin: string, eventName: string, payload: TelemetryPayload): Promise<Context | null>;
    page(page: string, payload: TelemetryPayload): Promise<Context | null>;
    screen(view: string, payload: TelemetryPayload): Promise<Context | null>;
    identify(payload?: TelemetryPayload): Promise<Context | null>;
}

export class NullValueTelemetry implements ITelemetry {
    public track() {
        return Promise.resolve(null);
    }

    public identify() {
        return Promise.resolve(null);
    }

    public page() {
        return Promise.resolve(null);
    }

    public screen() {
        return Promise.resolve(null);
    }
}

export const getTracker = (): ITelemetry => {
    // @ts-ignore: Custom type for `window` doesn't work in some CI steps
    const telemetry = window.epi?.telemetry as ITelemetry;
    if (!telemetry) {
        return new NullValueTelemetry();
    }
    return telemetry;
};
