import "./side-bar-navigation.scss";

import { Link, ProgressDots, Sidebar, SidebarMenuItem, Typography, VerticalTab } from "@optimizely/axiom";
import { debounce } from "lodash";
import React, { FunctionComponent, useEffect, useState } from "react";
import OutsideClickHandler from "react-outside-click-handler";

import { MenuItem, MenuItemBehavior } from "../navigation.types";

interface SecondLevelNavigation {
    levelTwo?: MenuItem;
    menuItem: MenuItem;
    onItemSelect: (levelTwo: MenuItem, evt?: React.MouseEvent | Event) => void;
    isActive: (menuItem: MenuItem) => boolean;
}

const isStartWithCurrentUrl = (menuItem: { url: string }) => {
    if (!menuItem?.url) {
        return false;
    }

    let pathAndQuery =
        ((window.location?.pathname || "") + window.location?.search + window.location?.hash).toLocaleLowerCase() ||
        "/";
    if (!pathAndQuery.endsWith("/")) {
        pathAndQuery += "/";
    }

    let menuUrl = menuItem.url.toLocaleLowerCase();
    if (!menuUrl.endsWith("/")) {
        menuUrl += "/";
    }

    // We depend on HashRouter, so any hash should be removed when comparing.
    pathAndQuery = pathAndQuery.replace("#", "");
    menuUrl = menuUrl.replace("#", "");

    return pathAndQuery.startsWith(menuUrl) && menuUrl !== pathAndQuery;
};

const ThirdLevelNavigationItem = ({ menuItem, onItemSelect, isActive }: SecondLevelNavigation) => {
    return (
        <VerticalTab.NavItem
            key={menuItem.name}
            isActive={isActive(menuItem)}
            testSection="prod-item"
            leftContent={
                <Link isFullWidth={true} onClick={(evt) => onItemSelect(menuItem, evt)} href={menuItem.url}>
                    <Typography type="body" tag="span">
                        {menuItem.name}
                    </Typography>
                </Link>
            }
        />
    );
};

export interface SideBarNavigationProps {
    menuItems: MenuItem[];
    levelOne?: MenuItem;
    levelTwo?: MenuItem;

    onItemSelect: (levelOne: MenuItem, levelTwo: MenuItem, evt?: React.MouseEvent | Event) => void;
    isActive: (menuItem: MenuItem) => boolean;
}

interface CustomMenuItemProps {
    isOpen: boolean;
    title: string;
    tooltip?: string;
    showTooltip: boolean;
    icon: string;
    cssClass?: string;
    href: string;
    onClick: (evt: React.MouseEvent | Event) => void;
    isActive?: boolean;
    submenus: React.ReactNode;
    isSubmenu?: boolean;
}

const CustomMenuItem = ({
    isOpen,
    title,
    tooltip,
    showTooltip,
    icon,
    cssClass,
    href,
    onClick,
    isActive,
    submenus,
    isSubmenu,
}: CustomMenuItemProps) => {
    return (
        <span key={title} title={showTooltip ? (tooltip ?? title) : ""} onClick={(evt) => onClick(evt)}>
            <SidebarMenuItem
                title={title}
                leftIcon={icon}
                className={cssClass}
                href={href}
                isCollapsed={!isOpen}
                isSubmenuItem={isSubmenu}
                isActive={isActive}
                submenus={submenus}
            />
        </span>
    );
};

export const SideBarNavigation: FunctionComponent<SideBarNavigationProps> = ({
    menuItems,
    levelOne,
    levelTwo,
    onItemSelect,
    isActive,
}) => {
    const [isOpen, setIsOpen] = useState<boolean>(true);
    const [shouldHideSecondNavigationPanel, setShouldHideSecondNavigationPanel] = useState<boolean>(false);

    const isSidebarOpen = () => {
        if (!levelOne) {
            return false;
        }

        if (levelOne.children?.length && levelOne.children?.length > 0) {
            return false;
        }

        if (levelOne.behavior === MenuItemBehavior.Hide) {
            return false;
        }

        return true;
    };

    const checkShouldHideSecondNavigationPanel = (levelOne: MenuItem | undefined): boolean => {
        return (
            !!levelOne &&
            levelOne.children.length > 0 &&
            levelOne.children.some((x) => {
                if (x.behavior === MenuItemBehavior.HideForChildNavigation) {
                    return isStartWithCurrentUrl(x);
                }

                return checkShouldHideSecondNavigationPanel(x);
            })
        );
    };

    useEffect(() => {
        setIsOpen(isSidebarOpen());

        const hashChangeHandler = debounce(() => {
            setShouldHideSecondNavigationPanel(checkShouldHideSecondNavigationPanel(levelOne));
        }, 128);

        window.addEventListener("hashchange", hashChangeHandler);

        return () => {
            hashChangeHandler.cancel();
            window.removeEventListener("hashchange", hashChangeHandler);
        };
    }, [levelOne]);

    const addonMenuItems = menuItems?.filter((x) => !x.isePiMenuItem);

    const buildAddonSubMenus = (): React.ReactNode => {
        return (
            <>
                {addonMenuItems.map((y) => (
                    <CustomMenuItem
                        key={y.name}
                        isOpen={isOpen}
                        title={y.name}
                        tooltip={y.tooltip}
                        showTooltip={!!y.tooltip}
                        icon={""}
                        cssClass={`flex--inline flex-justified--center flex-align--center link-sub ${y.cssClass || ""}`}
                        href={y.url}
                        onClick={(evt) => onItemSelect(y, y.children[0], evt)}
                        isActive={isActive(y)}
                        isSubmenu={true}
                        submenus={null}
                    />
                ))}
            </>
        );
    };

    return (
        <OutsideClickHandler onOutsideClick={() => setIsOpen(isSidebarOpen())}>
            <div className="epi-side-bar-navigation">
                <div className="epi-side-bar-navigation-left-menu">
                    <Sidebar
                        anchor="left"
                        border={true}
                        borderColor="#E8E8E8"
                        backgroundColor="smoke"
                        isOpen={isOpen}
                        isFullHeight={true}
                        width={208}
                        collapsedWidth={52}
                        docked
                        sticky
                    >
                        <div className="soft-half--bottom soft-double--top">
                            {!menuItems || (menuItems.length < 1 && <ProgressDots />)}
                            {menuItems
                                .filter((x) => x.isePiMenuItem)
                                .map((x) => (
                                    <CustomMenuItem
                                        key={x.name}
                                        isOpen={isOpen}
                                        title={x.name}
                                        tooltip={x.tooltip}
                                        showTooltip={!isOpen}
                                        icon={x.iconName || "puzzle-piece-thin"}
                                        cssClass={x.cssClass}
                                        href={x.url}
                                        onClick={(evt) => onItemSelect(x, x.children[0], evt)}
                                        isActive={isActive(x)}
                                        submenus={null}
                                    />
                                ))}
                            {addonMenuItems && addonMenuItems.length > 0 && (
                                <CustomMenuItem
                                    key={"Add-ons"}
                                    isOpen={isOpen}
                                    title={"Add-ons"}
                                    showTooltip={!isOpen}
                                    icon={"puzzle-piece-thin"}
                                    cssClass={""}
                                    href={""}
                                    onClick={() => {
                                        setIsOpen(true);
                                        return false;
                                    }}
                                    isActive={false}
                                    submenus={buildAddonSubMenus()}
                                />
                            )}
                        </div>
                    </Sidebar>
                </div>
                {levelOne && levelOne.children.length > 0 && !shouldHideSecondNavigationPanel && (
                    <VerticalTab removeTopBodyPadding>
                        <VerticalTab.Header hasBackLink={false} primaryTitle={levelOne.name} />
                        {levelOne.children
                            .reduce(
                                (accumulator, currentValue) => {
                                    if (currentValue.children.length < 1) {
                                        accumulator[0].children.push(currentValue);
                                    } else {
                                        accumulator.push(currentValue);
                                    }

                                    return accumulator;
                                },
                                [{ name: "", children: [] as MenuItem[] }],
                            )
                            .map((menuItem) => {
                                return (
                                    <VerticalTab.NavList label={menuItem.name} key={menuItem.name}>
                                        {menuItem.children.map((childMenuItem: MenuItem) => (
                                            <ThirdLevelNavigationItem
                                                key={childMenuItem.name}
                                                levelTwo={levelTwo}
                                                menuItem={childMenuItem}
                                                onItemSelect={(levelThree) => onItemSelect(levelOne, levelThree)}
                                                isActive={isActive}
                                            />
                                        ))}
                                    </VerticalTab.NavList>
                                );
                            })}
                    </VerticalTab>
                )}
            </div>
        </OutsideClickHandler>
    );
};
