/*
    This is needed in order to keep the classes on the root node in sync with the classes on the navigation
    The platform navigation styles are expecting the navigation and the fixed-adjust to be siblings.
    We currently can't have that structure in CMS UI, as the dojo code can't live within the react container.
    The workaround is to copy the classes from the navigation to the root node, since the root node is a
    sibling of the fixed-adjust.
*/
export function observe(root: HTMLElement) {
    const navigationContainerClasses = "epi-navigation-container epi-navigationContainer";
    // This observer is responsible for copying the classes when the classes have changed
    const navObserver = new MutationObserver((mutationsList) => {
        mutationsList.forEach((mutation) => {
            root.className = `${(mutation.target as Element).className} ${navigationContainerClasses}`;
        });
    });
    // This observer is responsible for copying the classes when the navigation is added to the root node
    const rootObserver = new MutationObserver((mutationsList) => {
        mutationsList.forEach((mutation) => {
            if (mutation.addedNodes.length > 0) {
                // only copy classes of the first added node
                rootObserver.disconnect();
                root.className = `${(mutation.addedNodes[0] as Element).className} ${navigationContainerClasses}`;
                // observe the newly added node for class changes that will need to be mirrored in the root
                navObserver.observe(mutation.addedNodes[0], { attributes: true });
            }
        });
    });

    rootObserver.observe(root, { childList: true });
}
