import { useEffect, useState } from "react";

export type MessageUserFeedbackType = { text: string; isError: boolean };
export const initialData = { text: "", isError: false };
export const useUserFeedback = () => {
    const [message, setMessage] = useState<MessageUserFeedbackType>({ text: "", isError: false });

    const handleEvent = (event: any) => {
        const data: MessageUserFeedbackType = event.detail;
        setMessage(data);
    };

    useEffect(() => {
        document.addEventListener("setUserMessage", handleEvent);

        return () => {
            document.removeEventListener("setUserMessage", handleEvent);
        };
    }, []);

    return {
        message: message,
        setMessage: setMessage,
    };
};

export default useUserFeedback;
