import { getTracker, ITelemetry } from "@episerver/telemetry";

import { MenuItem, Product } from "./navigation.types.ts";

export function onNavigate(item: MenuItem | Product, callback?: () => void, event?: React.MouseEvent | Event) {
    const { url, target, path } = item as MenuItem;

    const navigate = () => {
        if (target) {
            window.open(url, target);
        } else {
            window.location.href = url;
        }
        if (typeof callback === "function") {
            setTimeout(() => {
                callback();
            }, 100);
        }
    };

    const tracker: ITelemetry = getTracker();
    if (tracker) {
        if (event) {
            // Prevent navigation from occuring if the tracker is available, so we can track the event first.
            event.preventDefault();
        }
        const payload = { url, path, timestamp: new Date().toISOString() };
        tracker.track("cms_navigation", "cms_navigate", payload).finally(navigate);
    } else {
        // If no tracker is available, just navigate.
        navigate();
    }
}
