import { getTracker } from "@episerver/telemetry";
import axios from "axios";
import { debounce } from "lodash";
import { useCallback, useEffect, useRef, useState } from "react";

import { isMatchUrl, normalizeUrl } from "./helpers/url-matcher.ts";
import { MenuItem, MenuItemBehavior } from "./navigation.types.ts";
import { onNavigate } from "./onNavigate.tsx";
import navigationRoot from "./parse-navigation-root.ts";

const tracker = getTracker();

const getMenuItem = (
    items: MenuItem[],
    value?: string,
    check: "path" | "url" = "url",
    closestMatch?: MenuItem,
): MenuItem | undefined => {
    if (!items || !value) {
        return closestMatch;
    }

    // Loop through the items
    for (const item of items) {
        if (check === "url") {
            if (isMatchUrl(item, value)) {
                return item;
            }

            const target = normalizeUrl(item.url);

            // If the current path starts with this item's URL, consider it the closest match
            if (value.startsWith(target)) {
                closestMatch = item;
            }
        } else if (check === "path") {
            if (item.path === value) {
                return item;
            }
        }

        if (item.children) {
            const found = getMenuItem(item.children, value, check, closestMatch);
            // The reason we need to match the path is to avoid returning the parent early.
            if (found && found.path !== closestMatch?.path) {
                return found;
            }
        }
    }

    return closestMatch;
};

const getActiveMenuItems = (menuItems: MenuItem[], path?: string, hash?: string): MenuItem[] => {
    // Problem: URLs for menu items do not matter when it comes to hierarchy, instead the `path` does.
    // Solution: Traverse the menu items until the correct item is found by URL, then return the item and every parent above it.
    const activeItems: MenuItem[] = [];

    // 1. Find the active item by current URL, recursively.
    const activeItem =
        getMenuItem(menuItems, normalizeUrl(path, hash), "url") || getMenuItem(menuItems, normalizeUrl(path), "url");

    if (activeItem) {
        // 2. Find the parent of the active item by splitting the item.path
        // Get all the path segments, combine successively and check if any of the items match the path.
        const segments = activeItem.path?.split("/").filter(Boolean) ?? [];

        let currentPath = "";
        for (const segment of segments) {
            currentPath += `/${segment}`;
            const parent = getMenuItem(menuItems, currentPath, "path");
            // If a parent exists, and the parent is not the active item, add it to the list of active items.
            if (parent && !activeItems.some((x) => x.path === parent.path) && activeItem.path !== parent.path) {
                activeItems.push(parent);
            }
        }

        activeItems.push(activeItem);
    }

    // 4. Return the sorted list of active items, with the closest parent first and the active item last.
    return activeItems;
};

const DEFAULT_MENU_ITEM: MenuItem = {
    name: "FAKE",
    url: "FAKE",
    children: [],
    path: "",
    behavior: MenuItemBehavior.Hide,
};

export const useMenuItems = (navigationUrl: string, contentLanguage?: string) => {
    const [navigationItems, setNavigationItems] = useState<MenuItem[]>([]);
    const [actionItems, setActionItems] = useState<MenuItem[]>([]);
    const [activeMenuItems, setActiveMenuItems] = useState<string[]>([]);
    const [levelOne, setLevelOne] = useState<MenuItem>(DEFAULT_MENU_ITEM);
    const [levelTwo, setLevelTwo] = useState<MenuItem>();
    const [viewModeUrl, setViewModelUrl] = useState("");

    // We need to keep track of the current active URL, so we can avoid tracking the same URL multiple times
    const currentActiveUrl = useRef<string>();

    const onMenuSelected = (levelOneItem: MenuItem, levelTwoItem: MenuItem, evt?: React.MouseEvent | Event): void => {
        onNavigate(levelTwoItem || levelOneItem, () => {}, evt);
    };

    const getFilteredMenuItems = (items: MenuItem[]): MenuItem[] => {
        return items
            .filter((x) => x.isAvailable !== false)
            .map((x) => {
                if (x.children?.length > 0) {
                    return Object.assign({}, x, { children: getFilteredMenuItems(x.children) });
                }
                return x;
            });
    };

    const shouldTrackActiveMenuItem = (urlToTrack: string, activeItemUrl: string): boolean => {
        if (!currentActiveUrl.current) {
            return true;
        }

        // For ex.:
        // urlToTrack = /ui/cms/content-types/edit/123
        // activeItemUrl = /ui/cms/content-types
        const isSubPage = urlToTrack.startsWith(activeItemUrl) && urlToTrack.length > activeItemUrl.length;

        return isSubPage || currentActiveUrl.current !== urlToTrack;
    };

    const trackActiveMenuItem = useCallback((items: MenuItem[]) => {
        if (!items) {
            return;
        }

        // Strip away all the hashes
        const url = normalizeUrl(window.top?.location.pathname, window.top?.location.hash);

        if (!url) {
            return;
        }

        const activeItem = getMenuItem(items, url);
        if (activeItem && activeItem.path && shouldTrackActiveMenuItem(url, normalizeUrl(activeItem.url))) {
            currentActiveUrl.current = url;
            tracker.page(activeItem.path, { path: activeItem.path, locale: navigationRoot.currentUiCulture });
        }
    }, []);

    useEffect(() => {
        axios
            .get(navigationUrl, {
                headers: {
                    Accept: "application/javascript, application/json",
                    "X-EPiContentLanguage": contentLanguage || "",
                },
            })
            .then((navigationResponse) => {
                const { actionItems, menuItems } = navigationResponse.data;

                setActionItems(actionItems);
                setNavigationItems(getFilteredMenuItems(menuItems));
            });
    }, []);

    useEffect(() => {
        window.epi = window.epi || {};

        window.epi.updateViewMode = (ctx) => {
            setViewModelUrl(ctx.publicUrl);
        };
    }, [actionItems]);

    useEffect(() => {
        if (!navigationItems || !navigationItems.length) {
            return;
        }

        const onUrlChange = debounce(() => {
            const activeItems = getActiveMenuItems(
                navigationItems,
                window.top?.location.pathname,
                window.top?.location.hash,
            );

            if (activeItems[0]) {
                setLevelOne(activeItems[0]);
            }

            if (activeItems[1]) {
                setLevelTwo(activeItems[1]);
            }

            if (!activeItems.length) {
                setLevelOne(DEFAULT_MENU_ITEM);
                setLevelTwo(undefined);
            }

            setActiveMenuItems(activeItems.map((x) => x.path));
            trackActiveMenuItem(navigationItems);
        }, 128);

        window.addEventListener("hashchange", onUrlChange); // for hash-based navigation

        // Initiate the first change in case `hashchange` doesn't trigger on the first load
        // We gave a high enough debounce that in the case that it does trigger, it shouldn't trigger twice unless you're on a really slow network.
        onUrlChange();

        return () => {
            window.removeEventListener("hashchange", onUrlChange);
            onUrlChange.cancel();
        };
    }, [navigationItems]);

    return {
        navigationItems,
        setNavigationItems,
        actionItems,
        levelOne,
        levelTwo,
        onMenuSelected,
        isActive: (menuItem: MenuItem) => activeMenuItems.includes(menuItem.path),
        viewModeUrl,
    };
};
