import { HelpIcon } from "./icons/help-icon.tsx";
import { PublicIcon } from "./icons/public-icon.tsx";
import { UserIcon } from "./icons/user-icon.tsx";
import { MenuItem } from "./navigation.types.ts";

export const getCmsUiIcon = (actionItem: MenuItem) => {
    switch (actionItem.path) {
        case "/global/help":
            return <HelpIcon />;
        case "/global/user":
            return <UserIcon />;
        case "/global/sites":
            return <PublicIcon />;
        default:
            return null;
    }
};
