import { IAuthState } from "../internal/modules/auth";
import { BaseState } from "../internal/modules/base.state";

export function getGlobalState() {
    return window.state?.getAll();
}

export function getAuthState() {
    return window.state?.get<IAuthState>("authState");
}

export function registerState<T>(state: BaseState<T>) {
    window.state?.register(state);
}
