import { format, formatDistanceToNow, Locale } from "date-fns";
// @ts-expect-error Cannot find types
import defaultLocale from "date-fns/_lib/defaultLocale";
import { da, de, enAU, enCA, enGB, enUS, es, fi, fr, it, ja, nb as no, nl, pl, sv, zhCN as zh } from "date-fns/locale";

const supportedLocales = [da, de, enUS, enGB, enCA, enAU, es, fi, fr, it, ja, no, nl, pl, sv, zh];

function getLocaleFromCultureName(cultureName: string): Locale {
    if (!cultureName) {
        return defaultLocale;
    }

    const directMatch = supportedLocales.find((x) => x.code === cultureName);

    if (directMatch) {
        return directMatch;
    }

    const code = cultureName.split("-")[0];
    const codeDirectMatch = supportedLocales.find((x) => x.code === code);
    return codeDirectMatch || defaultLocale;
}

/**
 * @returns a formatted date string like this `en-US: Apr 29, 1453`
 */
export const formatDate = (date: string | Date, cultureName: string) => {
    try {
        const dateToFormat = new Date(date);

        return format(dateToFormat, "PP", {
            locale: getLocaleFromCultureName(cultureName),
        });
    } catch {
        return "";
    }
};

/**
 * @returns a formatted distance string like '3 hours ago, 2 days ago` in `uiCultureName`
 *          if date is not a range then it will display a date formatted in `cultureName`
 */
export const formatDateWithDistanceToNow = (date: string | Date, cultureName: string, uiCultureName: string) => {
    try {
        const dateToFormat = new Date(date);
        const currentDate = new Date();
        if (currentDate.getDate() - dateToFormat.getDate() < 1) {
            return formatDistanceToNow(dateToFormat, {
                addSuffix: true,
                locale: getLocaleFromCultureName(uiCultureName),
            });
        }

        return formatDate(date, cultureName);
    } catch {
        return date as string;
    }
};
