import { BlockList, Link } from "@optimizely/axiom";
import { FunctionComponent } from "react";

export interface SearchResult {
    url: string;
    iconCssClass: string;
    title: string;
}

export interface SearchProvider {
    id: string;
    category: string;
}

interface SearchProviderResultProps {
    provider: SearchProvider;
    searchUrl: string;
    onItemClick: () => void;
    results: SearchResult[];
    searchTerm: string;
}

const getHighlightedText = (itemResult: SearchResult, hightLight: string) => {
    const hightLightTextOnly = hightLight.replace(/[^A-Za-z]/g, "");
    const parts = itemResult?.title?.split(new RegExp(`(${hightLightTextOnly})`, "gi"));
    return (
        <Link
            href={itemResult.url}
            leftIcon={itemResult.iconCssClass}
            className={`${!itemResult.iconCssClass ? "item-link-noicon" : ""} item-link`}
        >
            <div className="item-link__block">
                {parts.map((part, i) =>
                    part.toLowerCase() === hightLightTextOnly.toLowerCase() ? (
                        part.replace(/\s/gi, "\u00a0")
                    ) : (
                        <span key={i} className="epi-global-search-menu__list__inner__search-result--highlight">
                            {part.replace(/\s/gi, "\u00a0")}
                        </span>
                    ),
                )}
            </div>
        </Link>
    );
};

export const SearchProviderResult: FunctionComponent<SearchProviderResultProps> = (props) => {
    return (
        <>
            {props.results.length > 0 && (
                <BlockList.Category header={props.provider.category}>
                    <BlockList hasBorder={false} className="epi-global-notification-list-result-search">
                        {props.results.map((itemResult) => (
                            <BlockList.Item
                                key={itemResult.url}
                                title={itemResult.title}
                                onClick={props.onItemClick}
                                className="flex--1"
                            >
                                {getHighlightedText(itemResult, props.searchTerm)}
                            </BlockList.Item>
                        ))}
                    </BlockList>
                </BlockList.Category>
            )}
        </>
    );
};
