import "./global-notification.scss";

import { resources } from "@episerver/shared/resources";
import { Button, Icon, LayeredIcons, Link, Sidebar, Toolbar, Typography } from "@optimizely/axiom";
import axios from "axios";
import { FunctionComponent, useEffect, useRef, useState } from "react";
import InfiniteScroll from "react-infinite-scroll-component";
import OutsideClickHandler from "react-outside-click-handler";

import { TopBarMenu } from "../top-bar-menu/top-bar-menu";
import { GlobalNotificationProps, NotificationResult } from "./global-notification.d";
import { GlobalNotificationList } from "./global-notification-list";

export const GlobalNotification: FunctionComponent<GlobalNotificationProps> = (props) => {
    const [data, setData] = useState<NotificationResult[]>([]);
    const [isOpen, setIsOpen] = useState<boolean>(false);
    const [isFetching, setIsFetching] = useState<boolean>(false);
    const [hasMore, setHasMore] = useState<boolean>(true);
    const [hasUnRead, setHasUnRead] = useState<boolean>(false);
    const [currentPage, setCurrentPage] = useState(0);
    const minItemsPerPage = props.minItemsPerPage || 50;
    const hasUnReadIntervalChecking = useRef<number | undefined>(undefined);

    useEffect(() => {
        if (hasUnReadIntervalChecking.current) {
            return;
        }
        hasUnReadIntervalChecking.current = window?.setInterval(() => {
            if (!hasUnRead) {
                axios
                    .get(props.storeUrl + "/GetUnreadCount")
                    .then((result) => {
                        return result?.data;
                    })
                    .then((count) => {
                        setHasUnRead(count > 0);
                    });
            }
        }, /*interval checking time*/ 60 * 1000);

        return () => {
            if (hasUnReadIntervalChecking.current) {
                window?.clearInterval(hasUnReadIntervalChecking.current);
            }
        };
    }, [hasUnReadIntervalChecking]);

    // get notifications data
    const fetchData = (page: number) => {
        if (isFetching) {
            return;
        }

        setIsFetching(true);

        const start = page * minItemsPerPage;
        const end = start + minItemsPerPage - 1;
        axios
            .get(props.storeUrl, {
                headers: {
                    itemsRange: `items=${start}-${end}`,
                },
            })
            .then((result: any) => {
                let items = result.data;
                if (page > 0) {
                    items = [...data, ...items];
                }

                setData(items);
                setHasUnRead(items.some((x: any) => !x.hasRead));
                let range = result.headers["items-content-range"];
                setHasMore(range && (range = range.match(/\/(.*)/)) && +range[1] > items.length);
            })
            .finally(() => {
                setIsFetching(false);
            });
    };

    useEffect(() => {
        fetchData(currentPage);
    }, [currentPage]);

    // force reload (always from page 0)
    const forceReload = () => {
        if (currentPage > 0) {
            setCurrentPage(0);
            return;
        }
        fetchData(0);
    };

    const notificationChannel = new BroadcastChannel(props.broadcastChannel || "/global/notification/message");
    // Listen to notification broadcasting channel
    useEffect(() => {
        notificationChannel.onmessage = (message) => {
            // show red dot whenever received real message from CMS hub.
            if (message.data.data) {
                setHasUnRead(true);
            }
            // stop interval due to we already have realtime commnunication
            if (hasUnReadIntervalChecking.current) {
                window?.clearInterval(hasUnReadIntervalChecking.current);
            }

            if (!isOpen) {
                return;
            }

            forceReload();
        };

        return () => {
            notificationChannel.close();
        };
    }, [notificationChannel]);

    // Listen to global click event then close notification bar.
    const handleClickOutside = () => {
        if (!isOpen) {
            return;
        }
        setIsOpen(false);
    };

    // Helper method get URL for input link.
    const parseUri = (link: string, origin: string | undefined = undefined): URL | undefined => {
        try {
            return new URL(link, origin);
        } catch (error) {
            // fallback with current origin
            if (!origin) {
                return parseUri(link, window?.location.origin);
            }
            return undefined;
        }
    };

    // Handle item click
    const onItemClick = (item: NotificationResult) => {
        if (!item) {
            return;
        }
        // async call to mark item as read
        if (!item.hasRead) {
            axios
                .get(props.storeUrl + "/markAsRead", {
                    params: {
                        id: item.id,
                    },
                })
                .then(() => {
                    setData(
                        data.map((x) => {
                            if (x.id === item.id) {
                                x.hasRead = true;
                            }

                            return x;
                        }),
                    );
                    setHasUnRead(data.some((x) => !x.hasRead));
                });
        }

        // call custom onclick event from props if existed.
        props.onItemClick && props.onItemClick(item);

        // hide notification list
        setIsOpen(false);

        // publish event to change context
        if (!item || !item.link) {
            return;
        }

        const isHashChangeOnly = (uri: URL) => {
            const currentUri = window?.location;
            return !["host", "pathname"].some((segment) => {
                //@ts-expect-error TODO: Typescript error - Something is wrong here, URL object cannot be indexed by strings
                return currentUri[segment] !== uri[segment];
            });
        };

        const uri = parseUri(item.link);
        if (uri && uri.host && window) {
            if (isHashChangeOnly(uri)) {
                window.location.hash = uri.hash;
                return;
            }
            // do fully reload
            window.location.href = uri.toString();
            return;
        }
    };

    const markAllAsRead = () => {
        if (!hasUnRead) {
            return;
        }

        axios.post(props.storeUrl + "/markAllAsRead").then(() => {
            setData(
                data.map((item) => {
                    item.hasRead = true;
                    return item;
                }),
            );
            setHasUnRead(false);
        });

        setIsOpen(false);
    };

    return (
        <OutsideClickHandler onOutsideClick={handleClickOutside}>
            <div className="epi-global-notification">
                <TopBarMenu
                    icon={
                        <LayeredIcons size="medium">
                            <Icon name="bell" size="small" />
                            <Icon
                                name="circle-small-solid"
                                size="small"
                                color="colors.redDark"
                                className={hasUnRead ? "" : "hidden"}
                            />
                        </LayeredIcons>
                    }
                    onOpen={() => {
                        if (!isOpen) {
                            forceReload();
                        }
                        setIsOpen(!isOpen);
                    }}
                    tooltip={props.tooltip}
                />
                <Sidebar
                    className={"epi-global-notification-list " + (isOpen ? "open" : "close")}
                    boxShadow={true}
                    isOpen={isOpen}
                    border={true}
                    isResizable={true}
                    sticky={true}
                >
                    <div id="globalNotificationSidebarContentContainer" className="epi-global-notification-list-inner">
                        <InfiniteScroll
                            dataLength={data.length}
                            next={() => setCurrentPage(currentPage + 1)}
                            hasMore={hasMore}
                            scrollableTarget="globalNotificationSidebarContentContainer"
                            loader={undefined}
                        >
                            <div className="epi-global-notification-list-header">
                                <Toolbar toolbarStyle={["bare"]}>
                                    <Toolbar.Left>
                                        <Typography type="header3" tag="span">
                                            {resources.episerver.cms.notification.list.header}
                                        </Typography>
                                    </Toolbar.Left>
                                    <Toolbar.Right>
                                        {hasUnRead && (
                                            <Button style="unstyled" onClick={markAllAsRead}>
                                                <Link>
                                                    {resources.episerver.cms.notification.command.markallasread}
                                                </Link>
                                            </Button>
                                        )}
                                    </Toolbar.Right>
                                </Toolbar>
                            </div>
                            <GlobalNotificationList
                                onItemClick={onItemClick}
                                items={data}
                                cultureName={props.cultureName}
                                uiCultureName={props.uiCultureName}
                            />
                        </InfiniteScroll>
                    </div>
                </Sidebar>
            </div>
        </OutsideClickHandler>
    );
};
