import { BlockList, Dropdown } from "@optimizely/axiom";
import { useState } from "react";

import { CmsProduct, MenuItem, Product } from "./navigation.types.ts";
import { onNavigate } from "./onNavigate.tsx";
import { useProducts } from "./useProducts.tsx";

interface ProductDropdownProps {
    productsUrl: string;
    parentProductId?: string;
    currentProductId?: string;
    setNavigationItems: (menuItems: MenuItem[]) => void;
}

export function ProductDropdown({
    productsUrl,
    parentProductId,
    currentProductId,
    setNavigationItems,
}: ProductDropdownProps) {
    const products = useProducts(productsUrl);
    const [productId, setProductId] = useState(parentProductId || currentProductId);

    const currentProduct = products.find((product) => product.id === productId) || { name: "", url: "" };

    const onProductSelect = (product: Product, evt?: React.MouseEvent | Event) => {
        const cmsProduct = product as CmsProduct;
        if (cmsProduct.children && cmsProduct.children.length) {
            // re-set currentProductId so that the correct product name will show
            // when not calling onNavigate
            setProductId(cmsProduct.id);
            // only re-set navigation items when the product has any children
            setNavigationItems(cmsProduct.children);
        } else {
            onNavigate(product, undefined, evt);
        }
    };

    const productSelectorIsDiabled = () => {
        return !products || products.length < 2;
    };

    return (
        <Dropdown
            buttonContent={currentProduct?.name || "CMS"}
            arrowIcon={productSelectorIsDiabled() ? "none" : "down"}
            isDisabled={productSelectorIsDiabled()}
            className={productSelectorIsDiabled() ? "disabled" : ""}
        >
            <Dropdown.Contents>
                {products.map((item) => (
                    <BlockList.Category header={null} key={item.id}>
                        <Dropdown.BlockLink
                            onClick={(evt: React.MouseEvent | Event) => onProductSelect(item, evt)}
                            isDisabled={currentProduct.url === item.url}
                        >
                            <a href={item.url} className="flex flex-align--center" title={item.tooltip}>
                                <span className="flex--1 truncate">{item.name}</span>
                            </a>
                        </Dropdown.BlockLink>
                    </BlockList.Category>
                ))}
            </Dropdown.Contents>
        </Dropdown>
    );
}
