import "./axios-config";
import "./navigation-optiid.scss";

import { getAuthState, IAuthState } from "@episerver/cms-global-state";
import { Navigation as AxiomNavigation } from "@optimizely/axiom";
import lightBrandLogoUrl from "@optimizely/design-tokens/dist/brand-assets/brand-logo-white.svg";
import { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { createRoot } from "react-dom/client";

import { CentralUserFeedback } from "./CentralUserFeedback";
import SlashForwardIcon from "./icons/slash-forward-icon";
import { ActionMenuItems } from "./navigation-menu-item.tsx";
import { observe } from "./navigationObserver";
import { onNavigate } from "./onNavigate.tsx";
import OptiActionsPanel from "./opti-actions-panel/opti-actions-panel";
import parseNavigationRoot from "./parse-navigation-root.ts";
import { ProductDropdown } from "./product-dropdown.tsx";
import { SideBarNavigation } from "./side-bar-navigation/side-bar-navigation";
import { useMenuItems } from "./useMenuItems.tsx";

const {
    searchUrl,
    searchProvidersUrl,
    navigationUrl,
    productsUrl,
    contentLanguage,
    currentCulture,
    currentProductId,
    currentUiCulture,
    parentProductId,
    shellUrl,
    sideBarNavigationRoot,
    root,
} = parseNavigationRoot;

// detect opti common header root node and listen when its ready
const optiCommonHeaderRoot = document.getElementsByTagName("opti-common-header")[0];
const commonHeaderBaseUrl = optiCommonHeaderRoot?.getAttribute("base-url");
const logoutUrl = optiCommonHeaderRoot?.getAttribute("logout-url");

const CmsNavigation = () => {
    const {
        navigationItems,
        setNavigationItems,
        actionItems,
        levelOne,
        levelTwo,
        onMenuSelected,
        isActive,
        viewModeUrl,
    } = useMenuItems(navigationUrl, contentLanguage);

    const axiomHeaderRef = useRef<HTMLDivElement>(null);
    const commonHeaderWrapperRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const unsubscribe = getAuthState()?.subscribe((state: IAuthState) => {
            const authToken = state.token;
            if (authToken) {
                // Update the token in the header.
                optiCommonHeaderRoot?.setAttribute("auth-token", authToken);
            }
        });

        return () => unsubscribe?.();
    }, []);

    useEffect(() => {
        let productSwitcherRoot = null;
        let productSwitcherSlot = null;

        // [TEMPORARY] On page load
        // TODO: Finalize moving the opti-common-header to the client side and removing the tag helper
        // This code should be moved to a separate opti-common-header wrapper component eventually
        if (optiCommonHeaderRoot && commonHeaderWrapperRef.current) {
            // Move the opti-common-header into the wrapper to prevent layout issues and flickering
            commonHeaderWrapperRef.current.appendChild(optiCommonHeaderRoot);

            const onReady = () => {
                if (axiomHeaderRef.current) {
                    // Hide the header
                    axiomHeaderRef.current.style.display = "none";
                }

                // Remove the listener
                optiCommonHeaderRoot.removeEventListener("@opti-common-header:ready", onReady);
            };

            // Listen to the opti-common-header ready event
            optiCommonHeaderRoot.addEventListener("@opti-common-header:ready", onReady, { once: true });

            // Render the product selector inside the "system-component" slot of the header
            // This is a temporary solution until the common header supports a different slot
            // The only reason this works as of today is because we hide the other buttons in the header
            // Create the container slot for the product switcher
            productSwitcherSlot = document.createElement("div");
            productSwitcherSlot.setAttribute("slot", "system-component");
            optiCommonHeaderRoot.appendChild(productSwitcherSlot);

            // Render the products selector
            productSwitcherRoot = createRoot(productSwitcherSlot);
            productSwitcherRoot.render(
                <div className="flex flex-align--center">
                    <span className="divider">
                        <SlashForwardIcon />
                    </span>

                    <ProductDropdown
                        currentProductId={currentProductId}
                        setNavigationItems={setNavigationItems}
                        productsUrl={productsUrl}
                        parentProductId={parentProductId}
                    />
                </div>,
            );
        }

        return () => {
            // Cleanup
            productSwitcherRoot?.unmount();
            productSwitcherSlot?.remove();
        };
    }, []);

    return (
        <>
            <div className="axiom-navigation__root" ref={axiomHeaderRef}>
                <AxiomNavigation logoUrl={lightBrandLogoUrl} theme={"dark"} title={"Optimizely"} />
            </div>

            <div className="navigation__root">
                <div ref={commonHeaderWrapperRef}></div>
            </div>

            <OptiActionsPanel>
                <ActionMenuItems
                    actionItems={actionItems}
                    viewModeUrl={viewModeUrl}
                    searchUrl={searchUrl}
                    searchProvidersUrl={searchProvidersUrl}
                    shellUrl={shellUrl}
                    currentUiCulture={currentUiCulture}
                    currentCulture={currentCulture}
                />
            </OptiActionsPanel>

            <CentralUserFeedback />
            {sideBarNavigationRoot &&
                createPortal(
                    <SideBarNavigation
                        menuItems={navigationItems}
                        onItemSelect={onMenuSelected}
                        levelOne={levelOne}
                        levelTwo={levelTwo}
                        isActive={isActive}
                    />,
                    sideBarNavigationRoot,
                )}
        </>
    );
};

// handle global common header request issue.
const isCommonHeaderRequest = (requestUrl: string) => {
    return (
        optiCommonHeaderRoot &&
        commonHeaderBaseUrl &&
        requestUrl.toLowerCase().startsWith(commonHeaderBaseUrl.toLowerCase())
    );
};
const confirmLogout = () => {
    if (optiCommonHeaderRoot && logoutUrl) {
        const okLogout = window.confirm("Something went wrong! Please logout then login again!");
        if (okLogout) {
            onNavigate({ name: "Logout", url: logoutUrl });
        }
    }
};
// monkey patching fetch
const { fetch: originalFetch } = window;
window.fetch = async (...args) => {
    const [resource, config] = args;
    try {
        //TODO: why do we need this strange code?
        const response = await originalFetch(resource, config);
        if (!response.ok && isCommonHeaderRequest(resource.toString())) {
            confirmLogout();
        }
        return response;
    } catch (error) {
        if (isCommonHeaderRequest(resource.toString())) {
            confirmLogout();
        }
        throw error;
    }
};

observe(root);
const reactRoot = createRoot(root);
reactRoot.render(<CmsNavigation />);
